steps.sql:
CREATE INDEX IF NOT EXISTS idx_employees_department ON employees(department);
CREATE INDEX IF NOT EXISTS idx_employees_status ON employees(status);
CREATE INDEX IF NOT EXISTS idx_timesheets_period ON timesheets(year, month);
CREATE INDEX IF NOT EXISTS idx_timesheets_employee ON timesheets(employee_id);
CREATE INDEX IF NOT EXISTS idx_archives_year ON archives(year);
CREATE INDEX IF NOT EXISTS idx_archives_employee ON archives(employee_id);
CREATE INDEX IF NOT EXISTS idx_archives_department ON archives(department);
CREATE INDEX IF NOT EXISTS idx_positions_department ON positions(department_id);
CREATE INDEX IF NOT EXISTS idx_departments_parent ON departments(parent_id);

CREATE TABLE IF NOT EXISTS candidates (
    id TEXT PRIMARY KEY,
    full_name TEXT NOT NULL,
    position TEXT NOT NULL,
    experience TEXT,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL,
    note TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_candidates_status ON candidates(status);
  CREATE TABLE IF NOT EXISTS time_off_requests (
    id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    type TEXT NOT NULL,
    date_from TEXT NOT NULL,
    date_to TEXT NOT NULL,
    days INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL,
    comment TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_time_off_requests_employee_id ON time_off_requests(employee_id);
  CREATE INDEX IF NOT EXISTS idx_time_off_requests_status ON time_off_requests(status);
  CREATE TABLE IF NOT EXISTS checklist_tasks (
    id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    kind TEXT NOT NULL,
    title TEXT NOT NULL,
    assignee TEXT,
    done INTEGER NOT NULL DEFAULT 0,
    comment TEXT,
    order_index INTEGER NOT NULL DEFAULT 0
  );
  CREATE INDEX IF NOT EXISTS idx_checklist_tasks_employee_id ON checklist_tasks(employee_id);
  CREATE TABLE IF NOT EXISTS goals (
    id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    title TEXT NOT NULL,
    progress INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL,
    period TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS idx_goals_employee_id ON goals(employee_id);
  CREATE INDEX IF NOT EXISTS idx_goals_status ON goals(status);
  CREATE TABLE IF NOT EXISTS reviews (
    id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    reviewer TEXT NOT NULL,
    period TEXT NOT NULL,
    score REAL NOT NULL DEFAULT 0,
    comment TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_reviews_employee_id ON reviews(employee_id);
  CREATE TABLE IF NOT EXISTS movements (
    id TEXT PRIMARY KEY,
    employee_id TEXT NOT NULL,
    type TEXT NOT NULL,
    date TEXT NOT NULL,
    from_position TEXT,
    to_position TEXT,
    from_department TEXT,
    to_department TEXT,
    from_salary REAL NOT NULL DEFAULT 0,
    to_salary REAL NOT NULL DEFAULT 0,
    order_no TEXT,
    reason TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_movements_employee_id ON movements(employee_id);
  CREATE INDEX IF NOT EXISTS idx_movements_date ON movements(date);
  CREATE TABLE IF NOT EXISTS audit_log (
    id TEXT PRIMARY KEY,
    ts TEXT NOT NULL,
    action TEXT NOT NULL,
    entity TEXT NOT NULL,
    entity_id TEXT,
    diff TEXT
  );
  CREATE TABLE IF NOT EXISTS report_presets (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    config TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS backups (
    id TEXT PRIMARY KEY,
    created_at TEXT NOT NULL,
    file_name TEXT NOT NULL,
    rows INTEGER NOT NULL DEFAULT 0,
    note TEXT
  );
  CREATE TABLE IF NOT EXISTS kb_categories (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    order_index INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS kb_articles (
    id TEXT PRIMARY KEY,
    category_id TEXT,
    title TEXT NOT NULL,
    content_html TEXT,
    reads INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS idx_kb_articles_category_id ON kb_articles(category_id);
